{"file_path":"/work/tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"small": [{"flagged": True}], "large": [{"flagged": None}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_trailing_window():
    counts = [3, 1, 2]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 3
    assert flags_in_window(counts, 4) == 6


def test_log_whitespace_comments_and_flags():
    lines = ["", " \t", "  # heading", " a , 2 , 0 ", " b , 3 ,  ", " c , 4 , 1 "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 3, "flagged": None},
        {"id": "c", "day": 4, "flagged": True},
    ]


@pytest.mark.parametrize("bad", ["a,2", "a,2,0,extra", "a,x,1"])
def test_log_errors_count_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "a,1,0", "", bad])


def test_dedupe_keeps_last_record_for_duplicate_id_then_sorts():
    events = parse_transcript_log(["b,4,1", "c,1,0", "b,2,0", "a,2,1"])
    assert dedupe_transcripts(events) == [events[1], events[3], events[2]]


def test_daily_counts_use_inclusive_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["x,1,1", "y,1,0"]), "b": parse_transcript_log(["z,4,1"]), "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"c": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_order_and_limit():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": None}], "a": [{"flagged": True}], "c": []}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_group_rates_include_empty_in_name_order():
    groups = {"z": [{"flagged": True}, {"flagged": None}], "a": []}
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("z", 0.5)]


@pytest.mark.parametrize("counts, length", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 1], 2)])
def test_streak_counts_consecutive_positive_entries(counts, length):
    assert longest_flag_streak(counts) == length
